// Attempting manual method dispatch by string matching type names
struct Scheduler;

impl Scheduler {
    fn lead_days(&self, target_class: &str) -> u32 {
        // String-based class matching to simulate polymorphic behavior
        match target_class {
            "Bicycle" => 1,
            "Mechanic" => 4,
            "Vehicle" => 3,
            _ => 0,
        }
    }
}
