fix:
Declare an interface trait and implement it directly on each target struct.

```
// Enforce dispatch via statically checked traits
pub trait Schedulable {
    fn lead_days(&self) -> u32;
}

pub struct Bicycle;
impl Schedulable for Bicycle {
    fn lead_days(&self) -> u32 { 1 }
}

pub struct Mechanic;
impl Schedulable for Mechanic {
    fn lead_days(&self) -> u32 { 4 }
}
